464	                    .orElseThrow(() -> new ShipmentException(
465	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
466	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
467	                    ));
468	
469	            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
