237	     * 3) Writer: DB에 반영 (상태 갱신)
238	     */
239	    @Bean
240	    @StepScope
241	    public JpaItemWriter<OrderShipment> shipmentJpaItemWriter() {
242	        log.debug("배송 상태 업데이트 ItemWriter 구성");
243	        JpaItemWriter<OrderShipment> writer = new JpaItemWriter<>();
244	        writer.setEntityManagerFactory(entityManagerFactory);
245	        return writer;
246	    }
